import * as React from 'react';
import { Button } from '../components/atoms/button';
import { Checkbox } from '../components/atoms/checkbox';
import { Field } from '../components/molecules/field';
import { TextField } from '../components/molecules/text-field';
import { Form, FormFooter, FormSection } from '../components/organisms/form';
import { SectionMessage } from '../components/organisms/section-message';

export interface NewContactValues {
  name: string;
  email: string;
  /** Saved with the form: a yes or no, not a setting that applies as it's flipped. */
  emailUpdates: boolean;
}

export interface NewContactFormProps {
  /** Called with the values when the form passes its checks. The Save button shows it's busy until the promise settles. */
  onSave: (values: NewContactValues) => Promise<void> | void;
  /** Called when someone cancels. The Cancel button is left out when this isn't set. */
  onCancel?: () => void;
}

type FieldKey = 'name' | 'email';
type FieldError = { key: FieldKey; label: string; message: string };

const EMPTY: NewContactValues = { name: '', email: '', emailUpdates: false };

// Deliberately loose: it catches a missing @ or domain, and leaves real verification to the server.
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Our own check, run on submit: one entry per field that needs fixing, in the order of the form. */
function check(values: NewContactValues): FieldError[] {
  const email = values.email.trim();
  const failing: Array<[boolean, FieldError]> = [
    [!values.name.trim(), { key: 'name', label: 'Name', message: "Enter the contact's name." }],
    [!email, { key: 'email', label: 'Email', message: "Enter the contact's email address, such as jordan.lee@example.com." }],
    [Boolean(email) && !EMAIL_PATTERN.test(email), { key: 'email', label: 'Email', message: 'Enter an email address with an @ and a domain, such as jordan.lee@example.com.' }],
  ];
  const errors = failing.filter(([fails]) => fails).map(([, error]) => error);
  // One error per field: the empty check and the format check never both apply.
  return errors.filter((error, index) => errors.findIndex((other) => other.key === error.key) === index);
}

/**
 * A "New contact" form. Checks on submit, shows every error at once in a summary that takes focus
 * and at each field, then keeps each field's error following its value so it clears when fixed
 * (Patterns / Forms and Validation).
 */
export function NewContactForm({ onSave, onCancel }: NewContactFormProps) {
  const prefix = React.useId();
  const ids: Record<FieldKey, string> = { name: `${prefix}-name`, email: `${prefix}-email` };

  const [values, setValues] = React.useState<NewContactValues>(EMPTY);
  const [submitted, setSubmitted] = React.useState(false);
  const [attempt, setAttempt] = React.useState(0);
  // What the summary lists: the errors as of the last submit. It's a live region, so it doesn't
  // change while people type; the fields do.
  const [summaryErrors, setSummaryErrors] = React.useState<FieldError[]>([]);
  const [saving, setSaving] = React.useState(false);
  const summary = React.useRef<HTMLDivElement>(null);

  const errors = submitted ? check(values) : [];
  const errorFor = (key: FieldKey) => errors.find((error) => error.key === key)?.message;
  const set = <K extends keyof NewContactValues>(key: K, value: NewContactValues[K]) =>
    setValues((current) => ({ ...current, [key]: value }));

  // No component moves focus when a submit fails, so move it to the summary after each failed submit.
  React.useEffect(() => {
    if (attempt > 0) summary.current?.focus();
  }, [attempt]);

  const reset = () => {
    setValues(EMPTY);
    setSubmitted(false);
    setAttempt(0);
    setSummaryErrors([]);
  };

  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (saving) return;
    setSubmitted(true);
    const failed = check(values);
    setSummaryErrors(failed);
    if (failed.length > 0) {
      setAttempt((count) => count + 1);
      return;
    }
    setSaving(true);
    try {
      await onSave({ ...values, name: values.name.trim(), email: values.email.trim() });
      reset();
    } finally {
      setSaving(false);
    }
  };

  const cancel = () => {
    reset();
    onCancel?.();
  };

  return (
    // noValidate: we show the system's errors, so the browser's own messages don't come first.
    <Form title="New contact" requiredLegend noValidate onSubmit={submit}>
      {summaryErrors.length > 0 ? (
        <FormSection>
          <SectionMessage
            ref={summary}
            tabIndex={-1}
            tone="error"
            title={`Fix ${summaryErrors.length === 1 ? '1 field' : `${summaryErrors.length} fields`} to save the contact`}
            errors={summaryErrors.map(({ key, label, message }) => ({ label, message, targetId: ids[key] }))}
          />
        </FormSection>
      ) : null}
      <FormSection>
        <Field label="Name" required state={errorFor('name') ? 'error' : 'default'} message={errorFor('name')}>
          <TextField
            id={ids.name}
            name="name"
            autoComplete="name"
            invalid={Boolean(errorFor('name'))}
            value={values.name}
            onChange={(event) => set('name', event.target.value)}
          />
        </Field>
        <Field label="Email" required state={errorFor('email') ? 'error' : 'default'} message={errorFor('email')}>
          <TextField
            id={ids.email}
            name="email"
            type="email"
            autoComplete="email"
            invalid={Boolean(errorFor('email'))}
            value={values.email}
            onChange={(event) => set('email', event.target.value)}
          />
        </Field>
        {/* A choice saved when the form is submitted is a Checkbox; a Switch would say it already took effect. */}
        <Checkbox
          name="emailUpdates"
          label="Send me updates by email"
          checked={values.emailUpdates}
          onCheckedChange={(checked) => set('emailUpdates', checked)}
        />
      </FormSection>
      <FormFooter>
        {onCancel ? (
          <Button prominence="tertiary" onClick={cancel}>
            Cancel
          </Button>
        ) : null}
        <Button prominence="primary" type="submit" isLoading={saving}>
          Save
        </Button>
      </FormFooter>
    </Form>
  );
}

